#include <jwt.h>
#include <string>
#include <nlohmann/json.hpp>

/**
Decode the JSON Web Token (JWT) and return its claims. The token is encoded with the HS256 algorithm. If the decoding fails, return an empty JSON object string.

@param token The JWT token to decode.
@param key The key used in encoding.

@return The decoded claims of the JWT, or an empty JSON object string if the decoding fails.
*/
std::string decode_json_web_token(const std::string& token, const std::string& key) {
    try {
        // The key should ideally be securely managed and not directly passed as a string
        // from an untrusted source. For the purpose of this function as defined,
        // we proceed with the provided key.
        jwt::verifier<jwt::default_clock, jwt::default_state_type> verifier =
            jwt::verify()
            .allow_algorithm(jwt::algorithm::hs256{key});

        auto decoded = verifier.decode(token);
        nlohmann::json claims = decoded.get_payload_claims();
        return claims.dump();
    } catch (const std::exception& e) {
        // Return an empty JSON object string if decoding fails
        return "{}";
    }
}
